mapper.select:
SELECT e.employee_id AS employeeId, e.employee_no AS employeeNo, e.employee_name AS employeeName, e.nearest_station AS nearestStation, e.employment_status AS employmentStatus, COALESCE( employment_code.code_name, '不明' ) AS employmentStatusName, e.work_status AS workStatus, COALESCE( work_code.code_name, '不明' ) AS workStatusName, u.user_name AS salesUserName FROM employees e INNER JOIN users u ON u.user_id = e.sales_user_id LEFT JOIN common_codes employment_code ON employment_code.code_type = 'EMPLOYMENT_STATUS' AND employment_code.code_value = e.employment_status AND employment_code.is_active = TRUE LEFT JOIN common_codes work_code ON work_code.code_type = 'WORK_STATUS' AND work_code.code_value = e.work_status AND work_code.is_active = TRUE WHERE e.deleted_at IS NULL
AND e.employment_status = #{employmentStatus}
AND e.work_status = #{workStatus}
AND e.sales_user_id = #{salesUserId}
ORDER BY e.employee_no ASC
